// Signaturprüfung gemäß Modul Webhooks des Immoware Hub (app/Modules/Webhooks/Services/WebhookSigner.php).
// Header X-Hub-Signature: t=<unix-sekunden>,v1=<hex HMAC-SHA256(secret, "<t>.<roher Body>")>
// Bei Secret-Rotation folgt ein zweiter Eintrag v1=<hex> für das alte Secret; ein Treffer genügt.
// Zusätzlich sendet der Hub X-Hub-Timestamp (gleicher Wert wie t), X-Hub-Event, X-Hub-Event-Id, X-Hub-Delivery.
const crypto = require('crypto');
const secret = $env.HUB_WEBHOOK_SECRET; // n8n-Credential oder Umgebungsvariable, nie im Workflow
if (!secret) { throw new Error('HUB_WEBHOOK_SECRET fehlt'); }

const item = $input.first().json;
const headers = item.headers || {};
const binary = $input.first().binary;
// Raw Body des Webhook-Nodes liegt base64-kodiert in binary.data; nur er ist byteidentisch mit dem signierten Body.
const rawBody = binary && binary.data && binary.data.data
  ? Buffer.from(binary.data.data, 'base64').toString('utf8')
  : (typeof item.body === 'string' ? item.body : JSON.stringify(item.body));
const header = headers['x-hub-signature'] || '';

let ts = null;
const candidates = [];
for (const part of header.split(',')) {
  const [k, v] = part.trim().split('=');
  if (k === 't' && /^\d+$/.test(v || '')) { ts = Number(v); }
  if (k === 'v1' && v) { candidates.push(v.toLowerCase()); }
}
if (ts === null || candidates.length === 0) { throw new Error('X-Hub-Signature unvollständig'); }

const now = Math.floor(Date.now() / 1000);
if (Math.abs(now - ts) > 300) { throw new Error('Zeitstempel außerhalb des Replay-Fensters (300 s)'); }

const expected = Buffer.from(crypto.createHmac('sha256', secret).update(`${ts}.${rawBody}`).digest('hex'));
const valid = candidates.some((c) => {
  const buf = Buffer.from(c);
  return buf.length === expected.length && crypto.timingSafeEqual(buf, expected);
});
if (!valid) { throw new Error('Signatur ungültig'); }

const payload = JSON.parse(rawBody);
if (payload.event !== 'open_item.created') { throw new Error(`Unerwartetes Ereignis ${payload.event}`); }
return [{ json: { ...payload, _hub_event_id: headers['x-hub-event-id'], _hub_delivery: headers['x-hub-delivery'] } }];

// Deduplizierung über event_id (Outbox-UUID). Ablage in Workflow Static Data; für Produktion Datenbank verwenden.
const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const id = $input.first().json.event_id;
if (staticData.seen[id]) { return []; }
staticData.seen[id] = Date.now();
// Einträge älter als 7 Tage entfernen
for (const [k, t] of Object.entries(staticData.seen)) { if (Date.now() - t > 7 * 86400 * 1000) { delete staticData.seen[k]; } }
return $input.all();
